queries.query:
find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| filter pe.status = "FAILED"
| aggregate { count() as failed_builds }

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| filter pe.status in ["ABORTED", "EXPIRED"]
| aggregate { count() as aborted_expired }

with runs as (
  find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
  | select { pe.pipelineidentifier as pipeline, pe.startts as ts, pe.status as status,
      lag(pe.status) over (partition by pe.pipelineidentifier order by pe.startts) as prev_status }
), fails as (
  find runs | filter status = "FAILED" and (prev_status is null or prev_status != "FAILED")
  | select { pipeline, ts as fail_ts }
), recov as (
  find runs | filter status = "SUCCESS" | select { pipeline as p2, ts as ok_ts }
), pairs as (
  find fails | join recov on recov.p2 = fails.pipeline | filter recov.ok_ts > fails.fail_ts
  | aggregate { fails.pipeline as pipeline, fails.fail_ts as fail_ts, min(recov.ok_ts) as ok_ts }
  | group_by pipeline, fail_ts
)
find pairs | aggregate { avg(date_diff(fail_ts, ok_ts, "second")) as mttr_s }

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| aggregate {
    date_trunc("week", pe.startts) as week,
    round(100.0 * count(case when pe.status = "FAILED" then 1 end) / nullif(count(), 0), 1) as failure_rate_pct,
    count(case when pe.status = "FAILED" then 1 end) as failed_builds
  }
| group_by week
| order_by week asc

find view "view:pipeline:stage_execution_failure" sf | inner join view "ci:pipeline_execution_summary_ci" pe on pe.planexecutionid = sf.plan_execution_id
| filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| aggregate { coalesce(nullif(sf.failure_type, ''), "UNCLASSIFIED") as failure_type, count() as failures }
| group_by failure_type
| order_by failures desc

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| aggregate {
    pe.projectidentifier as project,
    count(case when pe.status = "FAILED" then 1 end) as failed,
    count(case when pe.status in ["ABORTED", "EXPIRED"] then 1 end) as aborted_or_expired
  }
| group_by project
| having failed + aborted_or_expired > 0
| order_by failed desc
| limit 10

with agg as (
  find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
  | aggregate {
      pe.projectidentifier as project,
      pe.pipelineidentifier as pipeline,
      count() as builds,
      count(case when pe.status = "FAILED" then 1 end) as failed,
      count(case when pe.status in ["ABORTED", "EXPIRED"] then 1 end) as aborted_expired,
      round(100.0 * count(case when pe.status = "FAILED" then 1 end) / nullif(count(), 0), 1) as failure_rate_pct,
      max(case when pe.status = "FAILED" then pe.startts end) as last_failure
    }
  | group_by project, pipeline
  | having failed > 0
), ranked as (
  find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
  | select { pe.pipelineidentifier as lp, pe.status as latest_status,
      row_number() over (partition by pe.pipelineidentifier order by pe.startts desc) as rn }
), latest as (
  find ranked | filter rn = 1 | select { lp, latest_status }
)
find agg
| left join latest on latest.lp = agg.pipeline
| select { agg.project as project, agg.pipeline as pipeline, latest.latest_status as latest_status,
    agg.builds as builds, agg.failed as failed, agg.aborted_expired as aborted_expired,
    agg.failure_rate_pct as failure_rate_pct, agg.last_failure as last_failure }
| order_by failed desc
| limit 25

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| filter pe.status in ["ABORTED", "EXPIRED"]
| aggregate { date_trunc("week", pe.startts) as week, pe.status as status, count() as builds }
| group_by week, status
| order_by week asc
